# Debouncing a Search Input

## 1. A reusable debounce function

```js
function debounce(fn, delay = 300) {
  let timerId;

  const debounced = (...args) => {
    clearTimeout(timerId);
    timerId = setTimeout(() => fn(...args), delay);
  };

  debounced.cancel = () => clearTimeout(timerId);

  return debounced;
}
```

## 2. Apply it to the input

**Before** (fires on every keystroke):

```js
const input = document.querySelector('#search');

input.addEventListener('input', (e) => {
  search(e.target.value);
});
```

**After:**

```js
const input = document.querySelector('#search');

const debouncedSearch = debounce((query) => search(query), 300);

input.addEventListener('input', (e) => {
  debouncedSearch(e.target.value.trim());
});
```

The API call now only fires after the user has stopped typing for 300ms.

## 3. Handle stale responses (recommended)

Debouncing reduces calls, but a slow earlier request can still resolve *after* a later one and overwrite the correct results. Use `AbortController` to cancel the in-flight request:

```js
let controller;

async function search(query) {
  // Cancel any previous in-flight request
  controller?.abort();

  if (!query) {
    renderResults([]);
    return;
  }

  controller = new AbortController();

  try {
    const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
      signal: controller.signal,
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    renderResults(data);
  } catch (err) {
    if (err.name === 'AbortError') return; // expected, ignore
    console.error('Search failed:', err);
  }
}
```

## Full example

```html
<input id="search" type="search" placeholder="Search..." />
<ul id="results"></ul>

<script>
  function debounce(fn, delay = 300) {
    let timerId;
    const debounced = (...args) => {
      clearTimeout(timerId);
      timerId = setTimeout(() => fn(...args), delay);
    };
    debounced.cancel = () => clearTimeout(timerId);
    return debounced;
  }

  const input = document.querySelector('#search');
  const list = document.querySelector('#results');
  let controller;

  function renderResults(items) {
    list.innerHTML = '';
    for (const item of items) {
      const li = document.createElement('li');
      li.textContent = item.name; // textContent avoids XSS
      list.appendChild(li);
    }
  }

  async function search(query) {
    controller?.abort();
    if (!query) return renderResults([]);

    controller = new AbortController();
    try {
      const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
        signal: controller.signal,
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      renderResults(await res.json());
    } catch (err) {
      if (err.name !== 'AbortError') console.error(err);
    }
  }

  input.addEventListener(
    'input',
    debounce((e) => search(e.target.value.trim()), 300)
  );
</script>
```

## Notes

- **Delay:** 250-400ms is typical. Lower feels snappier, higher saves more requests.
- **Enter key:** If you want Enter to search immediately, call `debouncedSearch.cancel()` and then `search(input.value)` directly.
- **Cleanup:** If the input is removed from the DOM (for example in an SPA), call `debouncedSearch.cancel()` so a pending timer doesn't fire.

