# Debouncing a Search Input

## 1. A reusable debounce function

```javascript
function debounce(fn, delay = 300) {
  let timeoutId;

  return function (...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fn.apply(this, args), delay);
  };
}
```

Each call resets the timer, so `fn` only runs after the user has stopped typing for `delay` ms.

## 2. Apply it to your input

**Before:**
```javascript
const input = document.querySelector('#search');

input.addEventListener('input', (e) => {
  searchAPI(e.target.value);
});
```

**After:**
```javascript
const input = document.querySelector('#search');

const debouncedSearch = debounce((query) => {
  searchAPI(query);
}, 300);

input.addEventListener('input', (e) => {
  debouncedSearch(e.target.value.trim());
});
```

Create the debounced function **once**, outside the listener. If you call `debounce(...)` inside the handler, each keystroke gets its own timer and nothing is actually debounced.

## 3. Recommended: cancel stale requests

Debouncing reduces calls, but a slow response from an older query can still arrive after a newer one and overwrite the results. `AbortController` fixes this:

```javascript
let controller;

async function searchAPI(query) {
  // Cancel the previous in-flight request
  if (controller) controller.abort();

  if (!query) {
    renderResults([]);
    return;
  }

  controller = new AbortController();

  try {
    const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
      signal: controller.signal,
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);

    const data = await res.json();
    renderResults(data);
  } catch (err) {
    if (err.name === 'AbortError') return; // expected, ignore
    console.error('Search failed:', err);
  }
}
```

## Full example

```html
<input id="search" type="search" placeholder="Search..." />
<ul id="results"></ul>

<script>
  function debounce(fn, delay = 300) {
    let timeoutId;
    return function (...args) {
      clearTimeout(timeoutId);
      timeoutId = setTimeout(() => fn.apply(this, args), delay);
    };
  }

  let controller;

  async function searchAPI(query) {
    if (controller) controller.abort();
    if (!query) return renderResults([]);

    controller = new AbortController();

    try {
      const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
        signal: controller.signal,
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      renderResults(await res.json());
    } catch (err) {
      if (err.name !== 'AbortError') console.error(err);
    }
  }

  function renderResults(items) {
    document.querySelector('#results').innerHTML =
      items.map((item) => `<li>${item.name}</li>`).join('');
  }

  const debouncedSearch = debounce(searchAPI, 300);

  document.querySelector('#search').addEventListener('input', (e) => {
    debouncedSearch(e.target.value.trim());
  });
</script>
