```html
<input id="search" type="search" placeholder="Search..." />
<ul id="results"></ul>

<script>
  function debounce(fn, delay = 300) {
    let timeoutId;
    return function (...args) {
      clearTimeout(timeoutId);
      timeoutId = setTimeout(() => fn.apply(this, args), delay);
    };
  }

  let controller;

  async function fetchResults(query) {
    if (controller) controller.abort();
    if (!query) return renderResults([]);

    controller = new AbortController();

    try {
      const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
        signal: controller.signal,
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      renderResults(await res.json());
    } catch (err) {
      if (err.name !== 'AbortError') console.error(err);
    }
  }

  function renderResults(items) {
    document.querySelector('#results').innerHTML = items
      .map((item) => `<li>${item.name}</li>`)
      .join('');
  }

  const debouncedSearch = debounce(fetchResults, 300);

  document.querySelector('#search').addEventListener('input', (e) => {
    debouncedSearch(e.target.value.trim());
  });
</script>
```

## Notes

- **Delay:** 250–400 ms is a good range. Shorter feels snappier but sends more requests.
- **Create the debounced function once.** Don't call `debounce(...)` inside the event handler, or each keystroke gets its own timer and nothing is actually debounced.
- **Escape output:** if results contain user-generated content, use `textContent` or sanitize rather than `innerHTML`, to avoid XSS.

