```jsx
import { useState, useEffect, useRef } from "react";

function formatTime(totalSeconds) {
  const h = Math.floor(totalSeconds / 3600);
  const m = Math.floor((totalSeconds % 3600) / 60);
  const s = totalSeconds % 60;
  const pad = (n) => String(n).padStart(2, "0");
  return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${pad(m)}:${pad(s)}`;
}

export default function CountdownTimer({ seconds, autoStart = true, onComplete }) {
  const [remainingMs, setRemainingMs] = useState(seconds * 1000);
  const [isRunning, setIsRunning] = useState(autoStart);

  // Keep the latest onComplete without restarting the interval when it changes
  const onCompleteRef = useRef(onComplete);
  useEffect(() => {
    onCompleteRef.current = onComplete;
  }, [onComplete]);

  // Reset if the `seconds` prop changes
  useEffect(() => {
    setRemainingMs(seconds * 1000);
    setIsRunning(autoStart);
  }, [seconds, autoStart]);

  // Tick loop: computes time left from a fixed end timestamp,
  // so it doesn't drift like naive "subtract 1 each tick" timers.
  useEffect(() => {
    if (!isRunning) return;

    const endTime = Date.now() + remainingMs;

    const id = setInterval(() => {
      const left = Math.max(0, endTime - Date.now());
      setRemainingMs(left);

      if (left === 0) {
        clearInterval(id);
        setIsRunning(false);
        onCompleteRef.current?.();
      }
    }, 200);

    return () => clearInterval(id);
    // remainingMs is intentionally omitted: we only want to capture it
    // when starting/resuming, not restart the interval on every tick.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isRunning]);

  const displaySeconds = Math.ceil(remainingMs / 1000);
  const isFinished = remainingMs === 0;

  const handleReset = () => {
    setIsRunning(false);
    setRemainingMs(seconds * 1000);
  };

  return (
    <div style={{ textAlign: "center", fontFamily: "sans-serif" }}>
      <div
        style={{ fontSize: "3rem", fontVariantNumeric: "tabular-nums" }}
        role="timer"
        aria-live="off"
      >
        {formatTime(displaySeconds)}
      </div>

      {isFinished && <p>⏰ Time's up!</p>}

      <button onClick={() => setIsRunning((r) => !r)} disabled={isFinished}>
        {isRunning ? "Pause" : "Start"}
      </button>
      <button onClick={handleReset} style={{ marginLeft: 8 }}>
        Reset
      </button>
    </div>
  );
}
```

